static const char *reason_phrase(int code) { switch (code) { case 200:return "OK"; case 201:return "Created"; case 206:return "Partial Content"; case 400:return "Bad Request"; case 401:return "Unauthorized"; case 404:return "Not Found"; case 405:return "Method Not Allowed"; case 409:return "Conflict"; case 413:return "Payload Too Large"; case 416:return "Range Not Satisfiable"; case 500:return "Internal Server Error"; default:return "Error"; } }
static bool send_all(int fd,const void *data,size_t length){const char *p=data;while(length){ssize_t n=send(fd,p,length,0);if(n<=0)return false;p+=n;length-=(size_t)n;}return true;}
static void response(int fd,int code,const char *type,const char *body,size_t length){char *wrapped=NULL;const char *payload=body;size_t payload_length=length;if(!strcmp(type,"application/json")){const char *business=code>=200&&code<300?"0":code==401?"40101":code==404?"40401":code==409?"40902":code==413?"41301":code==400?"40001":"50001";const char *message=code>=200&&code<300?"success":"request failed";long long timestamp=(long long)time(NULL)*1000;size_t capacity=length+256;wrapped=malloc(capacity);if(!wrapped){json_error(fd,500,"out of memory");return;}int written=snprintf(wrapped,capacity,"{\"responseId\":\"local-%lld\",\"timestamp\":%lld,\"code\":\"%s\",\"message\":\"%s\",\"data\":%s}",timestamp,timestamp,business,message,body&&length?body:"null");if(written<0){free(wrapped);return;}payload=wrapped;payload_length=(size_t)written;}char header[512];int n=snprintf(header,sizeof(header),"HTTP/1.1 %d %s\r\nContent-Type: %s\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n",code,reason_phrase(code),type,payload_length);if(n>0)send_all(fd,header,(size_t)n);if(payload&&payload_length)send_all(fd,payload,payload_length);free(wrapped);}
static void json_error(int fd,int code,const char *message){char body[512];int n=snprintf(body,sizeof(body),"{\"error\":\"%s\"}",message);response(fd,code,"application/json",body,n>0?(size_t)n:0);}
static bool header_value(const char *headers,const char *name,char *value,size_t capacity){size_t name_len=strlen(name);const char *line=headers;while(line&&*line){const char *end=strstr(line,"\r\n");size_t length=end?(size_t)(end-line):strlen(line);if(length>name_len&&strncasecmp(line,name,name_len)==0&&line[name_len]==':'){const char *start=line+name_len+1;while((size_t)(start-line)<length&&(*start==' '||*start=='\t'))start++;size_t value_len=length-(size_t)(start-line);if(value_len>=capacity)value_len=capacity-1;memcpy(value,start,value_len);value[value_len]=0;return true;}line=end?end+2:NULL;}return false;}
static bool authorized(const char *headers){char proxy[160];if(agent_proxy_token[0]&&header_value(headers,"X-Agent-Proxy-Token",proxy,sizeof(proxy))&&!strcmp(proxy,agent_proxy_token))return true;char value[128];if(!header_value(headers,"Authorization",value,sizeof(value)))return false;pthread_mutex_lock(&auth_mutex);bool ok=!strcmp(value,"Bearer ")?false:!strncmp(value,"Bearer ",7)&&!strcmp(value+7,access_token)&&access_token[0]&&time(NULL)<access_expires;pthread_mutex_unlock(&auth_mutex);return ok;}
static bool parse_content_length(const char *headers,int64_t *result){char value[64],*end=NULL;if(!header_value(headers,"Content-Length",value,sizeof(value))){*result=0;return true;}errno=0;long long parsed=strtoll(value,&end,10);if(errno||end==value||*end||parsed<0)return false;*result=(int64_t)parsed;return true;}
static bool safe_relative(const char *input,char *output,size_t capacity){if(!input||input[0]=='/'||strstr(input,"\\")!=NULL||strstr(input,".se9-transfers"))return false;char copy[PATH_MAX];if(snprintf(copy,sizeof(copy),"%s",input)>=(int)sizeof(copy))return false;char *save=NULL;for(char *part=strtok_r(copy,"/",&save);part;part=strtok_r(NULL,"/",&save))if(!strcmp(part,".."))return false;while(*input=='/')input++;if(!*input||!strcmp(input,"."))return snprintf(output,capacity,"%s",storage_root)<(int)capacity;return snprintf(output,capacity,"%s/%s",storage_root,input)<(int)capacity;}
static bool reject_symlink(const char *path){struct stat st;if(lstat(path,&st)!=0)return true;return !S_ISLNK(st.st_mode);}
static const char *mime_type(const char *path){const char *dot=strrchr(path,'.');if(!dot)return "application/octet-stream";if(!strcasecmp(dot,".jpg")||!strcasecmp(dot,".jpeg"))return "image/jpeg";if(!strcasecmp(dot,".png"))return "image/png";if(!strcasecmp(dot,".gif"))return "image/gif";if(!strcasecmp(dot,".mp4"))return "video/mp4";if(!strcasecmp(dot,".mov"))return "video/quicktime";if(!strcasecmp(dot,".txt"))return "text/plain";return "application/octet-stream";}
static bool url_decode(const char *input,char *output,size_t capacity){size_t used=0;for(size_t i=0;input[i];i++){unsigned char c=(unsigned char)input[i];if(c=='%'){if(!input[i+1]||!input[i+2])return false;char hex[3]={input[i+1],input[i+2],0};char *end=NULL;long value=strtol(hex,&end,16);if(*end)return false;c=(unsigned char)value;i+=2;}else if(c=='+')c=' ';if(used+1>=capacity)return false;output[used++]=(char)c;}output[used]=0;return true;}
static bool mkdir_parents(const char *path){char copy[PATH_MAX];if(snprintf(copy,sizeof(copy),"%s",path)>=(int)sizeof(copy))return false;for(char *p=copy+1;*p;p++)if(*p=='/'){*p=0;if(mkdir(copy,0750)<0&&errno!=EEXIST)return false;*p='/';}return mkdir(copy,0750)==0||errno==EEXIST;}
static bool random_bytes(void *buffer,size_t length){int fd=open("/dev/urandom",O_RDONLY);if(fd<0)return false;unsigned char *p=buffer;size_t offset=0;while(offset<length){ssize_t n=read(fd,p+offset,length-offset);if(n<=0){close(fd);return false;}offset+=(size_t)n;}close(fd);return true;}
static bool random_id(char output[33]){unsigned char bytes[16];if(!random_bytes(bytes,sizeof(bytes)))return false;for(size_t i=0;i<sizeof(bytes);i++)snprintf(output+i*2,3,"%02x",bytes[i]);output[32]=0;return true;}
static bool extract_json_string(const char *json,const char *key,char *output,size_t capacity){char needle[128];if(snprintf(needle,sizeof(needle),"\"%s\"",key)>=(int)sizeof(needle))return false;const char *p=strstr(json,needle);if(!p)return false;p=strchr(p+strlen(needle),':');if(!p)return false;p++;while(*p==' '||*p=='\t')p++;if(*p!='\"')return false;p++;size_t used=0;while(*p&&*p!='\"'){if(*p=='\\'||used+1>=capacity)return false;output[used++]=*p++;}if(*p!='\"')return false;output[used]=0;return true;}
static bool extract_json_int64(const char *json,const char *key,int64_t *value){char needle[128],*end=NULL;if(snprintf(needle,sizeof(needle),"\"%s\"",key)>=(int)sizeof(needle))return false;const char *p=strstr(json,needle);if(!p)return false;p=strchr(p+strlen(needle),':');if(!p)return false;p++;while(*p==' '||*p=='\t')p++;errno=0;long long parsed=strtoll(p,&end,10);if(errno||end==p||parsed<0)return false;*value=(int64_t)parsed;return true;}
static bool read_request(http_request *request){size_t used=0;while(used<HEADER_MAX){unsigned char c;ssize_t n=recv(request->fd,&c,1,0);if(n<=0)return false;request->headers[used++]=(char)c;if(used>=4&&request->headers[used-4]=='\r'&&request->headers[used-3]=='\n'&&request->headers[used-2]=='\r'&&request->headers[used-1]=='\n')break;}if(used<4||used>=HEADER_MAX)return false;request->headers[used-4]=0;if(sscanf(request->headers,"%15s %1023s",request->method,request->target)!=2)return false;if(!parse_content_length(request->headers,&request->content_length))return false;request->prefetched_length=0;request->prefetched_offset=0;return true;}
static bool read_body(http_request *request,void *buffer,size_t length){unsigned char *out=buffer;size_t done=0;while(done<length){if(request->prefetched_offset<request->prefetched_length){size_t available=request->prefetched_length-request->prefetched_offset;size_t take=available<length-done?available:length-done;memcpy(out+done,request->prefetched+request->prefetched_offset,take);request->prefetched_offset+=take;done+=take;continue;}ssize_t n=recv(request->fd,out+done,length-done,0);if(n<=0)return false;done+=(size_t)n;}return true;}
static bool discard_body(http_request *request){int64_t remaining=request->content_length-(int64_t)request->prefetched_length;unsigned char buffer[65536];while(remaining>0){size_t take=remaining<(int64_t)sizeof(buffer)?(size_t)remaining:sizeof(buffer);if(!read_body(request,buffer,take))return false;remaining-=(int64_t)take;}return true;}
static bool read_json_body(http_request *request,char **body){if(request->content_length<0||request->content_length>JSON_MAX)return false;*body=calloc(1,(size_t)request->content_length+1);if(!*body)return false;if(!read_body(request,*body,(size_t)request->content_length)){free(*body);*body=NULL;return false;}return true;}
static void health(int fd){const char *body="{\"status\":\"ok\"}";response(fd,200,"application/json",body,strlen(body));}
static void issue_tokens(void){char access[33],refresh[33];if(!random_id(access)||!random_id(refresh))return;pthread_mutex_lock(&auth_mutex);snprintf(access_token,sizeof(access_token),"%s",access);snprintf(refresh_token,sizeof(refresh_token),"%s",refresh);access_expires=time(NULL)+3600;refresh_expires=time(NULL)+30*24*60*60;pthread_mutex_unlock(&auth_mutex);}
static void login(int fd,const char *body){const char *password=getenv("DEMO_ADMIN_PASSWORD");if(!password)password="change-me";char username[64],supplied[256];if(!extract_json_string(body,"username",username,sizeof(username))&&!extract_json_string(body,"account",username,sizeof(username)))username[0]=0;if(!extract_json_string(body,"password",supplied,sizeof(supplied))||strcmp(username,"admin")||strcmp(supplied,password)){json_error(fd,401,"invalid credentials");return;}issue_tokens();char result[256];pthread_mutex_lock(&auth_mutex);snprintf(result,sizeof(result),"{\"accessToken\":\"%s\",\"refreshToken\":\"%s\",\"expiresIn\":3600,\"user\":{\"userId\":\"admin\",\"account\":\"admin\"}}",access_token,refresh_token);pthread_mutex_unlock(&auth_mutex);response(fd,200,"application/json",result,strlen(result));}
static void refresh_auth(int fd,const char *body){char supplied[128];if(!extract_json_string(body,"refreshToken",supplied,sizeof(supplied))){json_error(fd,400,"invalid refresh token");return;}pthread_mutex_lock(&auth_mutex);bool valid=!strcmp(supplied,refresh_token)&&refresh_token[0]&&time(NULL)<refresh_expires;pthread_mutex_unlock(&auth_mutex);if(!valid){json_error(fd,401,"refresh token expired");return;}issue_tokens();char result[256];pthread_mutex_lock(&auth_mutex);snprintf(result,sizeof(result),"{\"accessToken\":\"%s\",\"refreshToken\":\"%s\",\"expiresIn\":3600}",access_token,refresh_token);pthread_mutex_unlock(&auth_mutex);response(fd,200,"application/json",result,strlen(result));}
static void logout_auth(int fd){pthread_mutex_lock(&auth_mutex);access_token[0]=0;refresh_token[0]=0;access_expires=refresh_expires=0;pthread_mutex_unlock(&auth_mutex);response(fd,200,"application/json","{}",2);}
static void list_files(int fd,const char *target){char relative[PATH_MAX]="",decoded[PATH_MAX];const char *query=strchr(target,'?');const char *raw=query?strstr(query,"path="):NULL;if(raw){raw+=5;size_t length=strcspn(raw,"&");char encoded[PATH_MAX];if(length>=sizeof(encoded)){json_error(fd,400,"invalid path");return;}memcpy(encoded,raw,length);encoded[length]=0;if(!url_decode(encoded,decoded,sizeof(decoded))){json_error(fd,400,"invalid path");return;}snprintf(relative,sizeof(relative),"%s",decoded);}char full[PATH_MAX];if(!safe_relative(relative,full,sizeof(full))){json_error(fd,400,"invalid path");return;}DIR *dir=opendir(full);if(!dir){json_error(fd,404,"directory not found");return;}size_t capacity=JSON_MAX,used=0;char *json=calloc(1,capacity);if(!json){closedir(dir);json_error(fd,500,"out of memory");return;}used+=(size_t)snprintf(json+used,capacity-used,"{\"path\":\"%s\",\"items\":[",relative);struct dirent *entry;bool first=true;while((entry=readdir(dir))){if(!strcmp(entry->d_name,".")||!strcmp(entry->d_name,"..")||!strcmp(entry->d_name,".se9-transfers"))continue;char child[PATH_MAX];snprintf(child,sizeof(child),"%s/%s",full,entry->d_name);struct stat st;if(stat(child,&st)!=0)continue;char item_path[PATH_MAX];snprintf(item_path,sizeof(item_path),"%s%s%s",relative,relative[0]?"/":"",entry->d_name);if(!first)used+=(size_t)snprintf(json+used,capacity-used,",");first=false;used+=(size_t)snprintf(json+used,capacity-used,"{\"name\":\"%s\",\"path\":\"%s\",\"directory\":%s,\"size\":%lld}",entry->d_name,item_path,S_ISDIR(st.st_mode)?"true":"false",(long long)st.st_size);if(used+512>=capacity)break;}closedir(dir);used+=(size_t)snprintf(json+used,capacity-used,"]}");response(fd,200,"application/json",json,used);free(json);}
static void remove_tree(const char *path){DIR *dir=opendir(path);if(!dir){unlink(path);return;}struct dirent *entry;while((entry=readdir(dir))){if(!strcmp(entry->d_name,".")||!strcmp(entry->d_name,"..")||!strcmp(entry->d_name,".se9-transfers"))continue;char child[PATH_MAX];if(snprintf(child,sizeof(child),"%s/%s",path,entry->d_name)>=(int)sizeof(child))continue;struct stat st;if(lstat(child,&st)==0){if(S_ISDIR(st.st_mode))remove_tree(child);else unlink(child);}}closedir(dir);rmdir(path);}
static void cleanup_uploads_locked(time_t now){for(size_t i=0;i<MAX_UPLOADS;i++){upload_session *upload=&uploads[i];if(!upload->active||now-upload->last_activity<=UPLOAD_TTL_SECONDS)continue;char dir[PATH_MAX];snprintf(dir,sizeof(dir),"%s/.uploading/%s",storage_root,upload->id);remove_tree(dir);free(upload->received);memset(upload,0,sizeof(*upload));}}
static upload_session *find_upload_locked(const char *id){for(size_t i=0;i<MAX_UPLOADS;i++)if(uploads[i].active&&!strcmp(uploads[i].id,id))return &uploads[i];return NULL;}
static bool sha256_file(const char *path,char output[65]){FILE *file=fopen(path,"rb");if(!file)return false;EVP_MD_CTX *ctx=EVP_MD_CTX_new();if(!ctx||EVP_DigestInit_ex(ctx,EVP_sha256(),NULL)!=1){fclose(file);EVP_MD_CTX_free(ctx);return false;}unsigned char buffer[65536];size_t n;while((n=fread(buffer,1,sizeof(buffer),file))>0)if(EVP_DigestUpdate(ctx,buffer,n)!=1){EVP_MD_CTX_free(ctx);fclose(file);return false;}unsigned char digest[EVP_MAX_MD_SIZE];unsigned int length=0;bool ok=ferror(file)==0&&EVP_DigestFinal_ex(ctx,digest,&length)==1;EVP_MD_CTX_free(ctx);fclose(file);if(!ok)return false;for(unsigned int i=0;i<length;i++)snprintf(output+i*2,3,"%02x",digest[i]);output[length*2]=0;return true;}
static void upload_session_create(int fd,http_request *request){char *body=NULL;if(!read_json_body(request,&body)){json_error(fd,request->content_length>JSON_MAX?413:400,"invalid request body");return;}char path[PATH_MAX],expected_sha256[65]="";int64_t size=0,chunk_size=DEFAULT_CHUNK_SIZE;bool valid=extract_json_string(body,"path",path,sizeof(path))&&extract_json_int64(body,"size",&size);(void)extract_json_int64(body,"chunkSize",&chunk_size);(void)extract_json_string(body,"sha256",expected_sha256,sizeof(expected_sha256));free(body);char full[PATH_MAX];if(!valid||size<=0||chunk_size<=0||chunk_size>MAX_CHUNK_SIZE||size>INT64_MAX-chunk_size+1||!safe_relative(path,full,sizeof(full))){json_error(fd,400,"invalid upload parameters");return;}int64_t chunks64=(size+chunk_size-1)/chunk_size;if(chunks64>1000000){json_error(fd,400,"invalid upload size");return;}pthread_mutex_lock(&uploads_mutex);upload_session *upload=NULL;for(size_t i=0;i<MAX_UPLOADS;i++)if(!uploads[i].active){upload=&uploads[i];break;}if(!upload){pthread_mutex_unlock(&uploads_mutex);json_error(fd,409,"too many uploads");return;}memset(upload,0,sizeof(*upload));if(!random_id(upload->id)){pthread_mutex_unlock(&uploads_mutex);json_error(fd,500,"cannot create upload id");return;}upload->received=calloc((size_t)chunks64,sizeof(bool));if(!upload->received){pthread_mutex_unlock(&uploads_mutex);json_error(fd,500,"out of memory");return;}upload->active=true;upload->size=size;upload->chunk_size=chunk_size;upload->total_chunks=(int)chunks64;snprintf(upload->relative_path,sizeof(upload->relative_path),"%s",path);snprintf(upload->expected_sha256,sizeof(upload->expected_sha256),"%s",expected_sha256);upload->last_activity=time(NULL);pthread_mutex_unlock(&uploads_mutex);char result[512];int n=snprintf(result,sizeof(result),"{\"uploadId\":\"%s\",\"chunkSize\":%lld,\"totalChunks\":%d,\"expiresIn\":%d}",upload->id,(long long)upload->chunk_size,upload->total_chunks,UPLOAD_TTL_SECONDS);response(fd,201,"application/json",result,(size_t)n);}
static bool parse_upload_target(const char *target,char id[33],int *index,const char **suffix){const char *prefix="/api/v2/upload/";if(strncmp(target,prefix,strlen(prefix)))return false;const char *start=target+strlen(prefix);if(!strncmp(start,"sessions/",9))start+=9;const char *slash=strchr(start,'/');if(!slash){if(strlen(start)!=32)return false;memcpy(id,start,32);id[32]=0;*suffix="";*index=-1;return true;}if((size_t)(slash-start)!=32)return false;memcpy(id,start,32);id[32]=0;*suffix=slash+1;if(!strncmp(*suffix,"chunks/",7)){char *end=NULL;long parsed=strtol(*suffix+7,&end,10);if(end==*suffix+7||*end||parsed<0||parsed>INT_MAX)return false;*index=(int)parsed;return true;}*index=-1;return !strcmp(*suffix,"complete")||!strcmp(*suffix,"missing")||!strcmp(*suffix,"status");}
static void upload_status(int fd,upload_session *upload){int missing=0,next=-1;for(int i=0;i<upload->total_chunks;i++)if(!upload->received[i]){missing++;if(next<0)next=i;}char result[512];int n=snprintf(result,sizeof(result),"{\"uploadId\":\"%s\",\"path\":\"%s\",\"size\":%lld,\"chunkSize\":%lld,\"totalChunks\":%d,\"receivedBytes\":%lld,\"missingChunks\":%d,\"nextChunk\":%d,\"status\":\"%s\"}",upload->id,upload->relative_path,(long long)upload->size,(long long)upload->chunk_size,upload->total_chunks,(long long)upload->received_bytes,missing,next,missing?"uploading":"ready");response(fd,200,"application/json",result,(size_t)n);}
static void upload_chunk(int fd,http_request *request,upload_session *upload,int index){if(index<0||index>=upload->total_chunks){json_error(fd,400,"invalid chunk index");return;}int64_t expected=upload->chunk_size;if(index==upload->total_chunks-1)expected=upload->size-(int64_t)index*upload->chunk_size;if(request->content_length!=expected){json_error(fd,400,"invalid chunk length");return;}char dir[PATH_MAX],part[PATH_MAX];snprintf(dir,sizeof(dir),"%s/.uploading/%s",storage_root,upload->id);if(!mkdir_parents(dir)){json_error(fd,500,"cannot create upload directory");return;}snprintf(part,sizeof(part),"%s/%08d.part",dir,index);int output=open(part,O_WRONLY|O_CREAT|O_TRUNC,0640);if(output<0){json_error(fd,500,"cannot create chunk");return;}unsigned char buffer[65536];int64_t remaining=request->content_length;bool ok=true;while(remaining>0){size_t take=remaining<(int64_t)sizeof(buffer)?(size_t)remaining:sizeof(buffer);if(!read_body(request,buffer,take)||write(output,buffer,take)!=(ssize_t)take){ok=false;break;}remaining-=(int64_t)take;}if(close(output)!=0)ok=false;if(!ok){unlink(part);json_error(fd,500,"chunk write failed");return;}if(!upload->received[index])upload->received_bytes+=expected;upload->received[index]=true;upload->last_activity=time(NULL);char result[256];int n=snprintf(result,sizeof(result),"{\"uploadId\":\"%s\",\"chunkIndex\":%d,\"receivedBytes\":%lld}",upload->id,index,(long long)upload->received_bytes);response(fd,200,"application/json",result,(size_t)n);}
static void upload_complete(int fd,upload_session *upload){for(int i=0;i<upload->total_chunks;i++)if(!upload->received[i]){json_error(fd,409,"missing upload chunk");return;}char final[PATH_MAX],temp[PATH_MAX],dir[PATH_MAX];if(!safe_relative(upload->relative_path,final,sizeof(final))){json_error(fd,400,"invalid upload path");return;}if(!reject_symlink(final)){json_error(fd,409,"destination is a symbolic link");return;}if(snprintf(temp,sizeof(temp),"%s.tmp.%s",final,upload->id)>=(int)sizeof(temp)||snprintf(dir,sizeof(dir),"%s/.uploading/%s",storage_root,upload->id)>=(int)sizeof(dir)){json_error(fd,400,"invalid upload path");return;}char parent[PATH_MAX];snprintf(parent,sizeof(parent),"%s",final);char *slash=strrchr(parent,'/');if(slash){*slash=0;if(!mkdir_parents(parent)||!reject_symlink(parent)){json_error(fd,500,"invalid destination directory");return;}}int output=open(temp,O_WRONLY|O_CREAT|O_TRUNC,0640);if(output<0){json_error(fd,500,"cannot create output file");return;}unsigned char buffer[65536];bool ok=true;for(int i=0;i<upload->total_chunks&&ok;i++){char part[PATH_MAX];snprintf(part,sizeof(part),"%s/%08d.part",dir,i);int input=open(part,O_RDONLY);if(input<0){ok=false;break;}ssize_t n;while((n=read(input,buffer,sizeof(buffer)))>0)if(write(output,buffer,(size_t)n)!=n){ok=false;break;}if(n<0)ok=false;close(input);}if(close(output)!=0)ok=false;if(!ok){unlink(temp);json_error(fd,500,"merge failed");return;}char actual[65];if(!sha256_file(temp,actual)){unlink(temp);json_error(fd,500,"hash failed");return;}if(upload->expected_sha256[0]&&strcasecmp(upload->expected_sha256,actual)){unlink(temp);json_error(fd,409,"sha256 mismatch");return;}if(rename(temp,final)){unlink(temp);json_error(fd,500,"cannot finalize file");return;}remove_tree(dir);char result[512];int n=snprintf(result,sizeof(result),"{\"status\":\"completed\",\"path\":\"%s\",\"size\":%lld,\"sha256\":\"%s\"}",upload->relative_path,(long long)upload->size,actual);response(fd,200,"application/json",result,(size_t)n);free(upload->received);memset(upload,0,sizeof(*upload));}
static void upload_route(int fd,http_request *request){char id[33];const char *suffix=NULL;int index=-1;if(!parse_upload_target(request->target,id,&index,&suffix)){json_error(fd,400,"invalid upload path");return;}pthread_mutex_lock(&uploads_mutex);cleanup_uploads_locked(time(NULL));upload_session *upload=find_upload_locked(id);if(!upload){pthread_mutex_unlock(&uploads_mutex);json_error(fd,404,"upload not found");return;}if(!strcmp(request->method,"PUT")&&index>=0)upload_chunk(fd,request,upload,index);else if(!strcmp(request->method,"GET")&&(!strcmp(suffix,"missing")||!strcmp(suffix,"status")))upload_status(fd,upload);else if(!strcmp(request->method,"POST")&&!strcmp(suffix,"complete"))upload_complete(fd,upload);else if(!strcmp(request->method,"DELETE")&&!*suffix){char dir[PATH_MAX];snprintf(dir,sizeof(dir),"%s/.uploading/%s",storage_root,upload->id);remove_tree(dir);free(upload->received);memset(upload,0,sizeof(*upload));response(fd,200,"application/json","{\"status\":\"cancelled\"}",22);}else json_error(fd,405,"method not allowed");pthread_mutex_unlock(&uploads_mutex);}
static void make_folder(int fd,http_request *request){char *body=NULL;if(!read_json_body(request,&body)){json_error(fd,400,"invalid request body");return;}char relative[PATH_MAX],full[PATH_MAX];bool valid=extract_json_string(body,"path",relative,sizeof(relative));free(body);if(!valid||!strcmp(relative,".")||!safe_relative(relative,full,sizeof(full))||!mkdir_parents(full)){json_error(fd,400,"invalid path");return;}response(fd,201,"application/json","{\"status\":\"ok\"}",15);}
static void download_file(int fd,http_request *request){const char *path=request->target+strlen("/api/v2/files/");char decoded[PATH_MAX],full[PATH_MAX];if(!url_decode(path,decoded,sizeof(decoded))||!safe_relative(decoded,full,sizeof(full))||!reject_symlink(full)){json_error(fd,400,"invalid path");return;}int input=open(full,O_RDONLY);if(input<0){json_error(fd,404,"file not found");return;}struct stat info;if(fstat(input,&info)||S_ISDIR(info.st_mode)){close(input);json_error(fd,404,"file not found");return;}off_t start=0,end=info.st_size?info.st_size-1:0;int status=200;char range[128];if(header_value(request->headers,"Range",range,sizeof(range))){if(strncmp(range,"bytes=",6)||info.st_size==0){close(input);char response_header[128];int n=snprintf(response_header,sizeof(response_header),"HTTP/1.1 416 Range Not Satisfiable\r\nContent-Range: bytes */%lld\r\nConnection: close\r\n\r\n",(long long)info.st_size);send_all(fd,response_header,(size_t)n);return;}char *dash=strchr(range+6,'-'),*endptr=NULL;if(!dash){close(input);json_error(fd,416,"invalid range");return;}*dash=0;long long parsed_start=strtoll(range+6,&endptr,10);if(endptr==range+6||*endptr||parsed_start<0){close(input);json_error(fd,416,"invalid range");return;}start=(off_t)parsed_start;if(dash[1]){long long parsed_end=strtoll(dash+1,&endptr,10);if(endptr==dash+1||*endptr||parsed_end<parsed_start){close(input);json_error(fd,416,"invalid range");return;}end=(off_t)parsed_end;}else end=info.st_size-1;if(start>=info.st_size){close(input);char response_header[128];int n=snprintf(response_header,sizeof(response_header),"HTTP/1.1 416 Range Not Satisfiable\r\nContent-Range: bytes */%lld\r\nConnection: close\r\n\r\n",(long long)info.st_size);send_all(fd,response_header,(size_t)n);return;}if(end>=info.st_size)end=info.st_size-1;status=206;}off_t length=info.st_size?end-start+1:0;if(lseek(input,start,SEEK_SET)<0){close(input);json_error(fd,500,"seek failed");return;}char header[512];int n;if(status==206)n=snprintf(header,sizeof(header),"HTTP/1.1 206 Partial Content\r\nContent-Type: %s\r\nContent-Disposition: attachment; filename=\"%s\"\r\nAccept-Ranges: bytes\r\nContent-Range: bytes %lld-%lld/%lld\r\nContent-Length: %lld\r\nConnection: close\r\n\r\n",mime_type(full),strrchr(full,'/')?strrchr(full,'/')+1:full,(long long)start,(long long)end,(long long)info.st_size,(long long)length);else n=snprintf(header,sizeof(header),"HTTP/1.1 200 OK\r\nContent-Type: %s\r\nContent-Disposition: attachment; filename=\"%s\"\r\nAccept-Ranges: bytes\r\nContent-Length: %lld\r\nConnection: close\r\n\r\n",mime_type(full),strrchr(full,'/')?strrchr(full,'/')+1:full,(long long)length);send_all(fd,header,(size_t)n);unsigned char buffer[65536];ssize_t count;off_t remaining=length;while(remaining>0&&(count=read(input,buffer,remaining<(off_t)sizeof(buffer)?(size_t)remaining:sizeof(buffer)))>0){if(!send_all(fd,buffer,(size_t)count))break;remaining-=count;}close(input);}
static void delete_file(int fd,const char *target){const char *path=target+strlen("/api/v2/files/");char decoded[PATH_MAX],full[PATH_MAX];if(!url_decode(path,decoded,sizeof(decoded))||!safe_relative(decoded,full,sizeof(full))||!strcmp(decoded,".")||!reject_symlink(full)){json_error(fd,400,"invalid path");return;}struct stat st;if(lstat(full,&st)!=0||S_ISDIR(st.st_mode)){json_error(fd,404,"file not found");return;}if(remove(full)){json_error(fd,404,"file not found");return;}response(fd,200,"application/json","{\"status\":\"deleted\"}",20);}
static void rename_file(int fd,http_request *request,const char *target){char *body=NULL,new_relative[PATH_MAX],old_decoded[PATH_MAX],old_full[PATH_MAX],new_full[PATH_MAX];if(!read_json_body(request,&body)){json_error(fd,400,"invalid request body");return;}bool valid=extract_json_string(body,"path",new_relative,sizeof(new_relative));free(body);const char *raw=target+strlen("/api/v2/files/");if(!url_decode(raw,old_decoded,sizeof(old_decoded))||!safe_relative(old_decoded,old_full,sizeof(old_full))||!valid||!safe_relative(new_relative,new_full,sizeof(new_full))||!strcmp(old_decoded,".")||!strcmp(new_relative,".")||!reject_symlink(old_full)||!reject_symlink(new_full)){json_error(fd,400,"invalid rename path");return;}if(access(old_full,F_OK)!=0){json_error(fd,404,"file not found");return;}char parent[PATH_MAX];if(snprintf(parent,sizeof(parent),"%s",new_full)>=(int)sizeof(parent)){json_error(fd,400,"invalid destination");return;}char *slash=strrchr(parent,'/');if(slash){*slash=0;if(!mkdir_parents(parent)){json_error(fd,500,"cannot create destination");return;}}if(rename(old_full,new_full)!=0){json_error(fd,409,"rename failed");return;}response(fd,200,"application/json","{\"status\":\"renamed\"}",20);}
static void handle_client(int fd){http_request request;memset(&request,0,sizeof(request));request.fd=fd;if(!read_request(&request)){json_error(fd,400,"invalid HTTP request");close(fd);return;}if(se9_transfer_handle(fd,request.method,request.target,request.headers,request.content_length)){close(fd);return;}if(!strcmp(request.method,"GET")&&!strncmp(request.target,"/api/v2/health",14)){health(fd);close(fd);return;}if(!strcmp(request.method,"POST")&&(!strcmp(request.target,"/api/v2/auth/login")||!strcmp(request.target,"/api/v2/auth/refresh"))){char *body=NULL;if(!read_json_body(&request,&body))json_error(fd,400,"invalid request body");else{if(!strcmp(request.target,"/api/v2/auth/login"))login(fd,body);else refresh_auth(fd,body);free(body);}close(fd);return;}if(!strcmp(request.method,"POST")&&!strcmp(request.target,"/api/v2/auth/logout")){if(!authorized(request.headers))json_error(fd,401,"unauthorized");else logout_auth(fd);close(fd);return;}if(!authorized(request.headers)){discard_body(&request);json_error(fd,401,"unauthorized");close(fd);return;}if(!strcmp(request.method,"POST")&&!strcmp(request.target,"/api/v2/upload/sessions"))upload_session_create(fd,&request);else if(!strncmp(request.target,"/api/v2/upload/",15))upload_route(fd,&request);else if(!strcmp(request.method,"GET")&&!strncmp(request.target,"/api/v2/files/",sizeof("/api/v2/files/")-1))download_file(fd,&request);else if(!strcmp(request.method,"PATCH")&&!strncmp(request.target,"/api/v2/files/",sizeof("/api/v2/files/")-1))rename_file(fd,&request,request.target);else if(!strcmp(request.method,"DELETE")&&!strncmp(request.target,"/api/v2/files/",sizeof("/api/v2/files/")-1))delete_file(fd,request.target);else if(!strcmp(request.method,"GET")&&!strncmp(request.target,"/api/v2/files",13))list_files(fd,request.target);else if(!strcmp(request.method,"POST")&&!strcmp(request.target,"/api/v2/folders"))make_folder(fd,&request);else{discard_body(&request);json_error(fd,404,"endpoint not implemented");}close(fd);}
static void *worker(void *arg){int fd=*(int *)arg;free(arg);struct timeval timeout={.tv_sec=30,.tv_usec=0};setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&timeout,sizeof(timeout));setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&timeout,sizeof(timeout));handle_client(fd);return NULL;}
int main(void){const char *root=getenv("STORAGE_ROOT");if(root)snprintf(storage_root,sizeof(storage_root),"%s",root);const char *port=getenv("FILE_API_PORT");if(port)listen_port=atoi(port);const char *bind_env=getenv("FILE_API_BIND_ADDR");if(bind_env&&*bind_env)snprintf(bind_address,sizeof(bind_address),"%s",bind_env);const char *proxy_env=getenv("SE9_AGENT_PROXY_TOKEN");if(proxy_env&&*proxy_env)snprintf(agent_proxy_token,sizeof(agent_proxy_token),"%s",proxy_env);if(!mkdir_parents(storage_root)){perror("storage root");return 1;}if(!se9_transfer_init(storage_root,agent_proxy_token)){fprintf(stderr,"transfer store initialization failed\n");return 1;}signal(SIGPIPE,SIG_IGN);int server=socket(AF_INET,SOCK_STREAM,0);if(server<0){perror("socket");return 1;}int yes=1;setsockopt(server,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));struct sockaddr_in address={.sin_family=AF_INET,.sin_addr.s_addr=inet_addr(bind_address),.sin_port=htons((uint16_t)listen_port)};if(bind(server,(struct sockaddr *)&address,sizeof(address))<0||listen(server,32)<0){perror("bind/listen");close(server);return 1;}printf("SE9 C file API listening on %s:%d, root=%s\n",bind_address,listen_port,storage_root);for(;;){int client=accept(server,NULL,NULL);if(client<0)continue;int *value=malloc(sizeof(int));if(!value){close(client);continue;}*value=client;pthread_t thread;if(pthread_create(&thread,NULL,worker,value)==0)pthread_detach(thread);else{free(value);close(client);}}}
